local shape_chunks = {}
for i = 1, 9 do
  shape_chunks[i] = MODULE .. string.format(".shapes_%03d", i)
end

local where -- shape name -> file number, built on the first lookup

-- The registry: a lookup of a shape not loaded yet loads its whole file. An unknown name is nil. A
-- missing file raises, as a missing module does.
local shapes = setmetatable({}, {
  __index = function(registry, name)
    if where == nil then
      where = {}
      for file, shape in string.gmatch(SHAPES, "(%d+) ([^\n]+)") do
        where[shape] = file
      end
      SHAPES = nil
    end
    local file = where[name]
    if file == nil then
      return nil
    end
    for k, node in pairs(require(MODULE .. ".shapes_" .. file)) do
      rawset(registry, k, node)
    end
    return rawget(registry, name)
  end,
})

local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
})
classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
})
classes.DatabaseNameNotAvailable = errors.define({
  tag = "DatabaseNameNotAvailable",
  categories = { "BadRequestError" },
  matchers = { { status = 422, message = { includes = "database name is not available" } } },
})
classes.FirewallTagNotFound = errors.define({
  tag = "FirewallTagNotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 422, message = { matches = "^tag .+ does not exist" } } },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
})
classes.GpuPlanUnavailable = errors.define({
  tag = "GpuPlanUnavailable",
  categories = { "BadRequestError" },
  matchers = {
    { status = 422, message = { includes = "is currently unavailable in this region" } },
  },
})
classes.InvalidProviderKey = errors.define({
  tag = "InvalidProviderKey",
  categories = { "BadRequestError" },
  matchers = {
    { status = 400, message = { includes = "invalid openai api key" } },
    { status = 400, message = { includes = "invalid anthropic key" } },
  },
})
classes.NamespaceDeleteConflict = errors.define({
  tag = "NamespaceDeleteConflict",
  categories = { "ConflictError" },
  matchers = { { status = 409, message = { includes = "conflict updating user doc" } } },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
})
classes.SecretPendingDeletion = errors.define({
  tag = "SecretPendingDeletion",
  categories = { "ConflictError" },
  matchers = { { status = 409, message = { includes = "conflict with the current state" } } },
})
classes.SshKeyAlreadyRegistered = errors.define({
  tag = "SshKeyAlreadyRegistered",
  categories = { "BadRequestError" },
  matchers = { { status = 422, message = { includes = "already in use" } } },
})
classes.UnprocessableEntity = errors.define({
  tag = "UnprocessableEntity",
  categories = { "BadRequestError" },
  matchers = { { status = 422 } },
})
classes.UptimeCheckNotFound = errors.define({
  tag = "UptimeCheckNotFound",
  categories = { "AuthError" },
  matchers = {
    { status = 403, message = { includes = "not authorized to access this resource" } },
  },
})
classes.VpcHasMembers = errors.define({
  tag = "VpcHasMembers",
  categories = { "ConflictError" },
  matchers = { { status = 409, message = { includes = "VPC with members" } } },
})
classes.VpcIsDefault = errors.define({
  tag = "VpcIsDefault",
  categories = { "AuthError" },
  matchers = { { status = 403, message = { includes = "delete default VPC" } } },
})

local ops = {}
for i = 1, 3 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "digitalocean.digitalocean",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "digitalocean-api",
    prefix = "DigitalOcean",
    service = "DigitalOcean",
    labels = "digitalocean",
    propagate = "w3c",
    response_headers = {
      { header = "x-request-id", name = "http.response.header.x-request-id", transform = "list" },
      { header = "request-id", name = "http.response.header.request-id", transform = "list" },
    },
  },
}
